window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0bf2638c839f790f"]={"versions": [{"id": "FIG-0bf2638c839f790f", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die Vererbungshierarchie und strukturellen Beziehungen der verschiedenen Arten von Ereignisauslöser-Bedingungen (<code>EventTriggeringConstraint</code>) innerhalb des Pakets bzw. Kontexts der Timing-Constraints und deren Zuordnung zu Timing-Beschreibungsereignissen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingConstraint::TimingConstraint</code>: Abstrakte Basisklasse, erbt von den Metaklassen <code>Identifiable</code> und <code>Traceable</code>.\n</li><li><code>EventTriggeringConstraint</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>TimingConstraint::TimingConstraint</code>. Sie besitzt eine gerichtete Assoziation mit der Rollenbezeichnung <code>+event</code> und der Kardinalität <code>1</code> auf das Zielelement <code>TimingDescription::TimingDescriptionEvent</code> (aus dem Paket <code>TimingDescription</code>).\n</li><li>Konkrete Spezialisierungen von <code>EventTriggeringConstraint</code> (über Vererbungspfeile abgeleitet):\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code>: Modellierung periodisch auftretender Ereignisauslösungen.\n</li><li><code>SporadicEventTriggering</code>: Modellierung sporadisch auftretender Ereignisse mit Mindestabständen.\n</li><li><code>BurstPatternEventTriggering</code>: Modellierung von transienten Lastspitzen bzw. Burst-Aktivierungsmustern.\n</li><li><code>ConcretePatternEventTriggering</code>: Modellierung deterministischer Aktivierungsmuster.\n</li><li><code>ArbitraryEventTriggering</code>: Modellierung beliebiger/irregulärer Ereignisfolgen.\n</li></ul>\n</li><li><code>TimingDescription::TimingDescriptionEvent</code>: Ziel-Metaklasse für das referenzierte Ereignis, das der Auslöser-Restriktion unterliegt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Struktur- bzw. Metamodell-Klassendiagramm bildet die Abbildung keinen zeitlichen Kontrollfluss oder dynamischen Sequenzablauf ab. Sie legt die deklarative Semantik fest, nach der ein definiertes Laufzeitereignis (<code>TimingDescriptionEvent</code>) genau einer formalen Auslöserestriktion (<code>EventTriggeringConstraint</code>) zugeordnet wird, welche das zulässige Eintreffen des Ereignisses zeitlich quantifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Autoren von AUTOSAR-Timing-Modellen und Tool-Hersteller:</p>\n<ul class=\"fig-list\"><li>Jede Instanz einer Spezialisierung von <code>EventTriggeringConstraint</code> muss zwingend genau ein Ereignis referenzieren (<code>+event</code> mit Multiplizität <code>1</code>). Ein Constraint ohne Ereignisreferenz ist metamodellwidrig.\n</li><li>Durch die Generalisierung von <code>TimingConstraint</code> und damit <code>Identifiable</code> sowie <code>Traceable</code> müssen Instanzen über einen eindeutigen <code>shortName</code> verfügen und unterstützen Nachverfolgbarkeit zu Anforderungen.\n</li><li>Werkzeuge zur Timing-Analyse müssen anhand des konkreten Subtyps (z. B. <code>PeriodicEventTriggering</code> vs. <code>SporadicEventTriggering</code>) die entsprechenden mathematischen Timing-Parameter validieren und auswerten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-893553a05feae1a3", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die Vererbungshierarchie und strukturellen Beziehungen der verschiedenen Arten von Ereignisauslöser-Bedingungen (<code>EventTriggeringConstraint</code>) innerhalb des Pakets bzw. Kontexts der Timing-Constraints und deren Zuordnung zu Timing-Beschreibungsereignissen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingConstraint::TimingConstraint</code>: Abstrakte Basisklasse, erbt von den Metaklassen <code>Identifiable</code> und <code>Traceable</code>.\n</li><li><code>EventTriggeringConstraint</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>TimingConstraint::TimingConstraint</code>. Sie besitzt eine gerichtete Assoziation mit der Rollenbezeichnung <code>+event</code> und der Kardinalität <code>1</code> auf das Zielelement <code>TimingDescription::TimingDescriptionEvent</code> (aus dem Paket <code>TimingDescription</code>).\n</li><li>Konkrete Spezialisierungen von <code>EventTriggeringConstraint</code> (über Vererbungspfeile abgeleitet):\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code>: Modellierung periodisch auftretender Ereignisauslösungen.\n</li><li><code>SporadicEventTriggering</code>: Modellierung sporadisch auftretender Ereignisse mit Mindestabständen.\n</li><li><code>BurstPatternEventTriggering</code>: Modellierung von transienten Lastspitzen bzw. Burst-Aktivierungsmustern.\n</li><li><code>ConcretePatternEventTriggering</code>: Modellierung deterministischer Aktivierungsmuster.\n</li><li><code>ArbitraryEventTriggering</code>: Modellierung beliebiger/irregulärer Ereignisfolgen.\n</li></ul>\n</li><li><code>TimingDescription::TimingDescriptionEvent</code>: Ziel-Metaklasse für das referenzierte Ereignis, das der Auslöser-Restriktion unterliegt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Struktur- bzw. Metamodell-Klassendiagramm bildet die Abbildung keinen zeitlichen Kontrollfluss oder dynamischen Sequenzablauf ab. Sie legt die deklarative Semantik fest, nach der ein definiertes Laufzeitereignis (<code>TimingDescriptionEvent</code>) genau einer formalen Auslöserestriktion (<code>EventTriggeringConstraint</code>) zugeordnet wird, welche das zulässige Eintreffen des Ereignisses zeitlich quantifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Autoren von AUTOSAR-Timing-Modellen und Tool-Hersteller:</p>\n<ul class=\"fig-list\"><li>Jede Instanz einer Spezialisierung von <code>EventTriggeringConstraint</code> muss zwingend genau ein Ereignis referenzieren (<code>+event</code> mit Multiplizität <code>1</code>). Ein Constraint ohne Ereignisreferenz ist metamodellwidrig.\n</li><li>Durch die Generalisierung von <code>TimingConstraint</code> und damit <code>Identifiable</code> sowie <code>Traceable</code> müssen Instanzen über einen eindeutigen <code>shortName</code> verfügen und unterstützen Nachverfolgbarkeit zu Anforderungen.\n</li><li>Werkzeuge zur Timing-Analyse müssen anhand des konkreten Subtyps (z. B. <code>PeriodicEventTriggering</code> vs. <code>SporadicEventTriggering</code>) die entsprechenden mathematischen Timing-Parameter validieren und auswerten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9b4c582b62ee8654", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die Vererbungshierarchie und strukturellen Beziehungen der verschiedenen Arten von Ereignisauslöser-Bedingungen (<code>EventTriggeringConstraint</code>) innerhalb des Pakets bzw. Kontexts der Timing-Constraints und deren Zuordnung zu Timing-Beschreibungsereignissen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingConstraint::TimingConstraint</code>: Abstrakte Basisklasse, erbt von den Metaklassen <code>Identifiable</code> und <code>Traceable</code>.\n</li><li><code>EventTriggeringConstraint</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>TimingConstraint::TimingConstraint</code>. Sie besitzt eine gerichtete Assoziation mit der Rollenbezeichnung <code>+event</code> und der Kardinalität <code>1</code> auf das Zielelement <code>TimingDescription::TimingDescriptionEvent</code> (aus dem Paket <code>TimingDescription</code>).\n</li><li>Konkrete Spezialisierungen von <code>EventTriggeringConstraint</code> (über Vererbungspfeile abgeleitet):\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code>: Modellierung periodisch auftretender Ereignisauslösungen.\n</li><li><code>SporadicEventTriggering</code>: Modellierung sporadisch auftretender Ereignisse mit Mindestabständen.\n</li><li><code>BurstPatternEventTriggering</code>: Modellierung von transienten Lastspitzen bzw. Burst-Aktivierungsmustern.\n</li><li><code>ConcretePatternEventTriggering</code>: Modellierung deterministischer Aktivierungsmuster.\n</li><li><code>ArbitraryEventTriggering</code>: Modellierung beliebiger/irregulärer Ereignisfolgen.\n</li></ul>\n</li><li><code>TimingDescription::TimingDescriptionEvent</code>: Ziel-Metaklasse für das referenzierte Ereignis, das der Auslöser-Restriktion unterliegt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Struktur- bzw. Metamodell-Klassendiagramm bildet die Abbildung keinen zeitlichen Kontrollfluss oder dynamischen Sequenzablauf ab. Sie legt die deklarative Semantik fest, nach der ein definiertes Laufzeitereignis (<code>TimingDescriptionEvent</code>) genau einer formalen Auslöserestriktion (<code>EventTriggeringConstraint</code>) zugeordnet wird, welche das zulässige Eintreffen des Ereignisses zeitlich quantifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Autoren von AUTOSAR-Timing-Modellen und Tool-Hersteller:</p>\n<ul class=\"fig-list\"><li>Jede Instanz einer Spezialisierung von <code>EventTriggeringConstraint</code> muss zwingend genau ein Ereignis referenzieren (<code>+event</code> mit Multiplizität <code>1</code>). Ein Constraint ohne Ereignisreferenz ist metamodellwidrig.\n</li><li>Durch die Generalisierung von <code>TimingConstraint</code> und damit <code>Identifiable</code> sowie <code>Traceable</code> müssen Instanzen über einen eindeutigen <code>shortName</code> verfügen und unterstützen Nachverfolgbarkeit zu Anforderungen.\n</li><li>Werkzeuge zur Timing-Analyse müssen anhand des konkreten Subtyps (z. B. <code>PeriodicEventTriggering</code> vs. <code>SporadicEventTriggering</code>) die entsprechenden mathematischen Timing-Parameter validieren und auswerten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5075427029650ff8", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die Vererbungshierarchie und strukturellen Beziehungen der verschiedenen Arten von Ereignisauslöser-Bedingungen (<code>EventTriggeringConstraint</code>) innerhalb des Pakets bzw. Kontexts der Timing-Constraints und deren Zuordnung zu Timing-Beschreibungsereignissen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingConstraint::TimingConstraint</code>: Abstrakte Basisklasse, erbt von den Metaklassen <code>Identifiable</code> und <code>Traceable</code>.\n</li><li><code>EventTriggeringConstraint</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>TimingConstraint::TimingConstraint</code>. Sie besitzt eine gerichtete Assoziation mit der Rollenbezeichnung <code>+event</code> und der Kardinalität <code>1</code> auf das Zielelement <code>TimingDescription::TimingDescriptionEvent</code> (aus dem Paket <code>TimingDescription</code>).\n</li><li>Konkrete Spezialisierungen von <code>EventTriggeringConstraint</code> (über Vererbungspfeile abgeleitet):\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code>: Modellierung periodisch auftretender Ereignisauslösungen.\n</li><li><code>SporadicEventTriggering</code>: Modellierung sporadisch auftretender Ereignisse mit Mindestabständen.\n</li><li><code>BurstPatternEventTriggering</code>: Modellierung von transienten Lastspitzen bzw. Burst-Aktivierungsmustern.\n</li><li><code>ConcretePatternEventTriggering</code>: Modellierung deterministischer Aktivierungsmuster.\n</li><li><code>ArbitraryEventTriggering</code>: Modellierung beliebiger/irregulärer Ereignisfolgen.\n</li></ul>\n</li><li><code>TimingDescription::TimingDescriptionEvent</code>: Ziel-Metaklasse für das referenzierte Ereignis, das der Auslöser-Restriktion unterliegt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Struktur- bzw. Metamodell-Klassendiagramm bildet die Abbildung keinen zeitlichen Kontrollfluss oder dynamischen Sequenzablauf ab. Sie legt die deklarative Semantik fest, nach der ein definiertes Laufzeitereignis (<code>TimingDescriptionEvent</code>) genau einer formalen Auslöserestriktion (<code>EventTriggeringConstraint</code>) zugeordnet wird, welche das zulässige Eintreffen des Ereignisses zeitlich quantifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Autoren von AUTOSAR-Timing-Modellen und Tool-Hersteller:</p>\n<ul class=\"fig-list\"><li>Jede Instanz einer Spezialisierung von <code>EventTriggeringConstraint</code> muss zwingend genau ein Ereignis referenzieren (<code>+event</code> mit Multiplizität <code>1</code>). Ein Constraint ohne Ereignisreferenz ist metamodellwidrig.\n</li><li>Durch die Generalisierung von <code>TimingConstraint</code> und damit <code>Identifiable</code> sowie <code>Traceable</code> müssen Instanzen über einen eindeutigen <code>shortName</code> verfügen und unterstützen Nachverfolgbarkeit zu Anforderungen.\n</li><li>Werkzeuge zur Timing-Analyse müssen anhand des konkreten Subtyps (z. B. <code>PeriodicEventTriggering</code> vs. <code>SporadicEventTriggering</code>) die entsprechenden mathematischen Timing-Parameter validieren und auswerten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9809d7b09f9256aa", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die Vererbungshierarchie und strukturellen Beziehungen der verschiedenen Arten von Ereignisauslöser-Bedingungen (<code>EventTriggeringConstraint</code>) innerhalb des Pakets bzw. Kontexts der Timing-Constraints und deren Zuordnung zu Timing-Beschreibungsereignissen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingConstraint</code>: Abstrakte Basisklasse, erbt von den Metaklassen <code>Identifiable</code> und <code>Traceable</code>.\n</li><li><code>EventTriggeringConstraint</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>TimingConstraint</code>. Sie besitzt eine gerichtete Assoziation mit der Rollenbezeichnung <code>+event</code> und der Kardinalität <code>0..1</code> auf das Zielelement <code>TimingDescriptionEvent</code> (aus dem Paket <code>TimingDescription</code>).\n</li><li>Konkrete Spezialisierungen von <code>EventTriggeringConstraint</code> (über Vererbungspfeile abgeleitet):\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code>: Modellierung periodisch auftretender Ereignisauslösungen.\n</li><li><code>SporadicEventTriggering</code>: Modellierung sporadisch auftretender Ereignisse mit Mindestabständen.\n</li><li><code>BurstPatternEventTriggering</code>: Modellierung von transienten Lastspitzen bzw. Burst-Aktivierungsmustern.\n</li><li><code>ConcretePatternEventTriggering</code>: Modellierung deterministischer Aktivierungsmuster.\n</li><li><code>ArbitraryEventTriggering</code>: Modellierung beliebiger/irregulärer Ereignisfolgen.\n</li></ul>\n</li><li><code>TimingDescriptionEvent</code>: Ziel-Metaklasse für das referenzierte Ereignis, das der Auslöser-Restriktion unterliegt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Struktur- bzw. Metamodell-Klassendiagramm bildet die Abbildung keinen zeitlichen Kontrollfluss oder dynamischen Sequenzablauf ab. Sie legt die deklarative Semantik fest, nach der ein definiertes Laufzeitereignis (<code>TimingDescriptionEvent</code>) genau einer formalen Auslöserestriktion (<code>EventTriggeringConstraint</code>) zugeordnet wird, welche das zulässige Eintreffen des Ereignisses zeitlich quantifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Autoren von AUTOSAR-Timing-Modellen und Tool-Hersteller:</p>\n<ul class=\"fig-list\"><li>Eine Instanz einer Spezialisierung von <code>EventTriggeringConstraint</code> kann optional maximal ein Ereignis referenzieren (<code>+event</code> mit Multiplizität <code>0..1</code>). Die Referenzierung eines <code>TimingDescriptionEvent</code> ist damit nicht mehr zwingend obligatorisch.\n</li><li>Durch die Generalisierung von <code>TimingConstraint</code> und damit <code>Identifiable</code> sowie <code>Traceable</code> müssen Instanzen über einen eindeutigen <code>shortName</code> verfügen und unterstützen Nachverfolgbarkeit zu Anforderungen.\n</li><li>Werkzeuge zur Timing-Analyse müssen anhand des konkreten Subtyps (z. B. <code>PeriodicEventTriggering</code> vs. <code>SporadicEventTriggering</code>) die entsprechenden mathematischen Timing-Parameter validieren und auswerten sowie den Fall abfangen können, dass kein Ereignis referenziert ist.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0bf2638c839f790f", "to": "FIG-893553a05feae1a3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-893553a05feae1a3", "to": "FIG-9b4c582b62ee8654", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9b4c582b62ee8654", "to": "FIG-5075427029650ff8", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5075427029650ff8", "to": "FIG-9809d7b09f9256aa", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Assoziation <code>+event</code> von <code>EventTriggeringConstraint</code> zu <code>TimingDescriptionEvent</code>: Multiplizität von <code>1</code> auf <code>0..1</code> geändert.\n</li><li>Klasse <code>TimingConstraint</code>: Paketpräfix <code>TimingConstraint::</code> entfernt.\n</li><li>Klasse <code>TimingDescriptionEvent</code>: Paketpräfix <code>TimingDescription::</code> entfernt.\n</li></ul>"}]};
